  // verify generated rules exist in stylesheets
  const findRule = (sel) => {
    for (const sheet of document.styleSheets) {
      let rules; try { rules = sheet.cssRules; } catch(e){ continue; }
      for (const r of rules) {
        if (r.selectorText && r.selectorText.includes(sel)) return r.cssText;
      }
    }
    return null;
  };
  return {
    outline2: findRule('outline-2'),
    outlineBlue: findRule('outline-blue-500'),
    focusBorder: findRule('focus\\:border-blue-500') || findRule('border-blue-500')
  };
}

